import React, { useState } from 'react';

function App(): JSX.Element {
  const [token, setToken] = useState<string>('');
  const [decodedToken, setDecodedToken] = useState<object | null>(null);

  const handleTokenChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    setToken(e.target.value);
  };

  const decodeToken = (): void => {
    if (token) {
      try {
        const payload = token.split('.')[1];
        const decoded = JSON.parse(atob(payload));
        setDecodedToken(decoded);
      } catch (error) {
        console.error('Failed to decode token:', error);
        setDecodedToken(null);
      }
    }
  };

  // Define saveTokenToStorage function here

  return (
    <div>
      <h1>JWT Storage & Decode</h1>
    </div>
  );
}

export default App;

